import { BooleanColumn, StringColumn, ScriptColumn, Table } from '../../db'

export const sys_script_fix = Table({
    name: 'sys_script_fix',
    extends: 'sys_metadata',
    schema: {
        name: StringColumn({ maxLength: 40 }),
        unloadable: BooleanColumn({ default: false }),
        before: BooleanColumn({ default: false }),
        record_for_rollback: BooleanColumn({ default: true }),
        description: StringColumn({ maxLength: 4000 }),
        script: ScriptColumn({}),
    },
})
